mapper.select:
select ifnull(max(watched_seconds), 0)
  from learning_points_watch
 where user_id = #{userId}
   and target_type = #{targetType}
   and target_id = #{targetId}
   and award_date = #{awardDate}

mapper.update:
update learning_points_watch
   set awarded = 1,
       points = #{points},
       update_time = sysdate()
 where user_id = #{userId}
   and target_type = #{targetType}
   and target_id = #{targetId}
   and award_date = #{awardDate}
   and awarded = 0
   and watched_seconds >= #{minSeconds}
